-- R3 C3-11: refuse to continue if an old install still has the pre-C-08 column types
DECLARE
  v_n NUMBER;
  v_bad VARCHAR2(500);
BEGIN
  FOR x IN (SELECT 'HV_MESSAGES' t, 'CREATED_AT' c FROM dual UNION ALL SELECT 'HV_MESSAGES' t, 'SENT_AT' c FROM dual UNION ALL SELECT 'HV_WEATHER_RAIN24' t, 'FETCHED_AT' c FROM dual UNION ALL SELECT 'HV_WEATHER_FETCH' t, 'LAST_ATTEMPT_AT' c FROM dual UNION ALL SELECT 'HV_WEATHER_FETCH' t, 'LAST_OK_AT' c FROM dual) LOOP
    SELECT COUNT(*) INTO v_n FROM user_tab_columns
     WHERE table_name = x.t AND column_name = x.c AND data_type LIKE 'TIMESTAMP%WITH TIME ZONE';
    IF v_n = 0 THEN v_bad := v_bad || ' ' || x.t || '.' || x.c; END IF;
  END LOOP;
  IF v_bad IS NOT NULL THEN
    RAISE_APPLICATION_ERROR(-20099, 'Old column types (need TIMESTAMP WITH TIME ZONE):' || v_bad
      || '. See plsql/README.md, Upgrading an existing install.');
  END IF;
END;
/


