-- Message templates (GSM-7 only, 2 SMS max after filling). Placeholders: {name}.
MERGE INTO hv_templates t USING (
SELECT 'RAIN_COVER' c, 'en' l, q'~Harvestly: Rain likely {rain_when} ({rain}). Cover your drying maize or bring it indoors now. Reply 1 when covered. {credit} {date}.~' b FROM dual
UNION ALL SELECT 'RAIN_COVER' c, 'sw' l, q'~Harvestly: Mvua inatarajiwa {rain_when} ({rain}). Funika mahindi unayoanika au uyaingize ndani sasa. Jibu 1 ukishafunika. {credit} {date}.~' b FROM dual
UNION ALL SELECT 'TEST_FIRST' c, 'en' l, q'~Harvestly: We do not know how wet your maize is yet. Test it before you store it: use a moisture meter at your co-op or NCPB depot and reply METER and the number, e.g. METER 14.2. Salt test (draft, unconfirmed): reply SALT YES if salt sticks, SALT NO if it stays loose.~' b FROM dual
UNION ALL SELECT 'TEST_FIRST' c, 'sw' l, q'~Harvestly: Hatujui bado mahindi yako yana unyevu kiasi gani. Yapime kabla ya kuhifadhi: tumia mita ya unyevu kwenye chama chako au bohari ya NCPB kisha jibu MITA na namba, mf. MITA 14.2. Kipimo cha chumvi (rasimu, bado hakijathibitishwa): jibu CHUMVI NDIYO chumvi ikinata, CHUMVI HAPANA ikibaki huru.~' b FROM dual
UNION ALL SELECT 'OPEN_AND_DRY' c, 'en' l, q'~Harvestly: Maize sealed at 14% moisture or more can still go mouldy ({evidence}). Storage time left: {risk}. Open the bags, dry the maize in full sun and reply DRYING. Reseal only after a test shows it is dry.~' b FROM dual
UNION ALL SELECT 'OPEN_AND_DRY' c, 'sw' l, q'~Harvestly: Mahindi yaliyofungwa yakiwa na unyevu wa 14% au zaidi bado yanaweza kuota kuvu ({evidence}). Muda uliobaki: {risk}. Fungua mifuko, anika juani kisha jibu ANIKA. Usifunge tena mpaka kipimo kionyeshe yamekauka.~' b FROM dual
UNION ALL SELECT 'CONFIRM_DRY' c, 'en' l, q'~Harvestly: Sealed bags protect maize only below 14% moisture, and this is not yet confirmed ({evidence}). Within a week, get a meter check at {checkpoint} and reply METER with the number.~' b FROM dual
UNION ALL SELECT 'CONFIRM_DRY' c, 'sw' l, q'~Harvestly: Mifuko isiyopitisha hewa hulinda mahindi yenye unyevu chini ya 14% tu, na hili bado halijathibitishwa ({evidence}). Ndani ya wiki moja, pima kwa mita katika {checkpoint} kisha tuma MITA na namba.~' b FROM dual
UNION ALL SELECT 'SORT_AND_SELL' c, 'en' l, q'~Harvestly: This batch has used most of its estimated storage time. Check it today: remove mouldy or discoloured grain (do not eat it or feed it to animals), then sell or use this batch first.~' b FROM dual
UNION ALL SELECT 'SORT_AND_SELL' c, 'sw' l, q'~Harvestly: Mahindi haya yametumia sehemu kubwa ya muda wa uhifadhi uliokadiriwa. Yakague leo: ondoa punje zenye kuvu au zilizobadilika rangi (usizile wala usiwalishe mifugo), kisha yauze au uyatumie kwanza.~' b FROM dual
UNION ALL SELECT 'HIGH_ALERT' c, 'en' l, q'~Harvestly: URGENT. Storage time left: {risk}. Check this maize today: remove mouldy or discoloured grain (do not eat it or feed it to animals), then sell or use it first. {closing}~' b FROM dual
UNION ALL SELECT 'HIGH_ALERT' c, 'sw' l, q'~Harvestly: HARAKA. Muda uliobaki: {risk}. Kagua mahindi haya leo: ondoa punje zenye kuvu au zilizobadilika rangi (usizile wala usiwalishe mifugo), kisha yauze au uyatumie kwanza. {closing}~' b FROM dual
UNION ALL SELECT 'DRY_NOW' c, 'en' l, q'~Harvestly: Your maize is too wet to store ({evidence}). Storage time left: {risk}. Dry it on a tarpaulin in full sun{reply_drying}, then test again. {credit} {date}.~' b FROM dual
UNION ALL SELECT 'DRY_NOW' c, 'sw' l, q'~Harvestly: Mahindi yako yana unyevu mwingi mno kuhifadhiwa ({evidence}). Muda uliobaki: {risk}. Yaanike juu ya turubai juani{reply_drying}, kisha pima tena. {credit} {date}.~' b FROM dual
UNION ALL SELECT 'RETEST' c, 'en' l, q'~Harvestly: {why} ({evidence}). Storage time left: {risk}. Do the salt test today and reply SALT YES or SALT NO. {credit} {date}.~' b FROM dual
UNION ALL SELECT 'RETEST' c, 'sw' l, q'~Harvestly: {why} ({evidence}). Muda uliobaki: {risk}. Fanya kipimo cha chumvi leo kisha jibu CHUMVI NDIYO au CHUMVI HAPANA. {credit} {date}.~' b FROM dual
UNION ALL SELECT 'NEARLY_DRY' c, 'en' l, q'~Harvestly: Not yet proven dry enough to seal or sell ({evidence}); the limit is 13.5%. Dry more in full sun if needed, then confirm with a meter at {checkpoint}. Reply METER and the number.~' b FROM dual
UNION ALL SELECT 'NEARLY_DRY' c, 'sw' l, q'~Harvestly: Bado haijathibitishwa kuwa mahindi yamekauka vya kutosha kufungwa au kuuzwa ({evidence}); kiwango ni 13.5%. Anika zaidi juani ikihitajika, kisha thibitisha kwa mita katika {checkpoint}. Jibu MITA na namba.~' b FROM dual
UNION ALL SELECT 'READY_TO_STORE' c, 'en' l, q'~Harvestly: Dry enough to store ({evidence}). Seal it in hermetic bags ({stockist}) or deposit it at {warehouse} for a warehouse receipt. Reply SEALED, SOLD or DEPOSITED when done.~' b FROM dual
UNION ALL SELECT 'READY_TO_STORE' c, 'sw' l, q'~Harvestly: Mahindi yamekauka vya kutosha ({evidence}). Yafunge kwenye mifuko isiyopitisha hewa ({stockist}) au yaweke kwenye {warehouse} upate stakabadhi ya ghala. Ukimaliza jibu NIMEFUNGA, NIMEUZA au GHALANI.~' b FROM dual
UNION ALL SELECT 'INSECT_REMINDER' c, 'en' l, q'~Harvestly: Your maize has been in sacks or open storage for {weeks} weeks. Weevil damage grows the longer maize stays in sacks. It tested dry, so consider moving it into hermetic bags ({stockist}) or selling soon.~' b FROM dual
UNION ALL SELECT 'INSECT_REMINDER' c, 'sw' l, q'~Harvestly: Mahindi yako yamekaa kwenye magunia au hifadhi ya wazi wiki {weeks}. Uharibifu wa fukusi huongezeka mahindi yakikaa muda mrefu kwenye magunia. Kipimo kilionyesha yamekauka, kwa hiyo fikiria kuyahamishia kwenye mifuko isiyopitisha hewa ({stockist}) au kuyauza mapema.~' b FROM dual
UNION ALL SELECT 'STATUS' c, 'en' l, q'~Harvestly: Recorded ({measured}). Storage time left: {risk}. This is an estimate, not a guarantee.~' b FROM dual
UNION ALL SELECT 'STATUS' c, 'sw' l, q'~Harvestly: Tumepokea ({measured}). Muda wa kuhifadhi uliobaki: {risk}. Ni makadirio, si hakikisho.~' b FROM dual
UNION ALL SELECT 'WELCOME' c, 'en' l, q'~Harvestly: Welcome. These messages give storage advice for your maize by SMS. It is an estimate. Weather data by Open-Meteo.com (CC BY 4.0). Reply STOP at any time to stop all messages.~' b FROM dual
UNION ALL SELECT 'WELCOME' c, 'sw' l, q'~Harvestly: Karibu. Ujumbe huu unatoa ushauri wa kuhifadhi mahindi yako kwa SMS. Ni makadirio. Data ya hali ya hewa: Open-Meteo.com (CC BY 4.0). Jibu SIMAMISHA wakati wowote kusimamisha ujumbe wote.~' b FROM dual
UNION ALL SELECT 'HELP' c, 'en' l, q'~Harvestly: Sorry, we did not understand. Reply SALT YES, SALT NO, METER 14.2, HYGRO 62 18, DRYING, SACKS, SEALED, SOLD, DEPOSITED or STOP.~' b FROM dual
UNION ALL SELECT 'HELP' c, 'sw' l, q'~Harvestly: Samahani, hatukuelewa. Jibu CHUMVI NDIYO, CHUMVI HAPANA, MITA 14.2, HYGRO 62 18, ANIKA, MAGUNIA, NIMEFUNGA, NIMEUZA, GHALANI au SIMAMISHA.~' b FROM dual
UNION ALL SELECT 'THANKS' c, 'en' l, q'~Harvestly: Thank you, noted.~' b FROM dual
UNION ALL SELECT 'THANKS' c, 'sw' l, q'~Harvestly: Asante, tumepokea.~' b FROM dual
UNION ALL SELECT 'START_OK' c, 'en' l, q'~Harvestly: Messages are on again for this number. To register grain reply JOIN <ward> <storage> <bags>, e.g. JOIN KITALE SACK 12. Reply STOP to stop.~' b FROM dual
UNION ALL SELECT 'START_OK' c, 'sw' l, q'~Harvestly: Ujumbe umewashwa tena kwa namba hii. Kusajili mahindi jibu SAJILI <kata> <hifadhi> <magunia>, mf. SAJILI KITALE MAGUNIA 12. Jibu SIMAMISHA kusimamisha.~' b FROM dual
UNION ALL SELECT 'CLOSED' c, 'en' l, q'~Harvestly: Noted. Alerts for this batch have ended. Reply START to restart them.~' b FROM dual
UNION ALL SELECT 'CLOSED' c, 'sw' l, q'~Harvestly: Tumepokea. Arifa za mahindi haya zimekoma. Jibu ANZA kuziwasha tena.~' b FROM dual
UNION ALL SELECT 'STOPPED' c, 'en' l, q'~Harvestly: You will get no more messages on this number, for any batch. Reply START to restart.~' b FROM dual
UNION ALL SELECT 'STOPPED' c, 'sw' l, q'~Harvestly: Hutapokea ujumbe zaidi kwenye namba hii, kwa mahindi yoyote. Jibu ANZA kuanza tena.~' b FROM dual
) s
ON (t.code = s.c AND t.lang = s.l)
WHEN MATCHED THEN UPDATE SET t.body = s.b
WHEN NOT MATCHED THEN INSERT (code, lang, body) VALUES (s.c, s.l, s.b);


COMMIT;
